  @protected
  void sse_encode_ui_event(UiEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case UiEvent_Progress(
        taskId: final taskId,
        stage: final stage,
        done: final done,
        total: final total,
        bytes: final bytes,
      ):
        sse_encode_i_32(0, serializer);
        sse_encode_u_64(taskId, serializer);
        sse_encode_String(stage, serializer);
        sse_encode_u_64(done, serializer);
        sse_encode_u_64(total, serializer);
        sse_encode_bool(bytes, serializer);
      case UiEvent_TaskFinished(
        taskId: final taskId,
        ok: final ok,
        message: final message,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_u_64(taskId, serializer);
        sse_encode_bool(ok, serializer);
        sse_encode_opt_String(message, serializer);
      case UiEvent_AccountsChanged():
        sse_encode_i_32(2, serializer);
      case UiEvent_GameStarted(
        gameId: final gameId,
        instanceId: final instanceId,
        pid: final pid,
      ):
        sse_encode_i_32(3, serializer);
        sse_encode_u_64(gameId, serializer);
        sse_encode_String(instanceId, serializer);
        sse_encode_opt_box_autoadd_u_32(pid, serializer);
      case UiEvent_GameLog(gameId: final gameId, lines: final lines):
        sse_encode_i_32(4, serializer);
        sse_encode_u_64(gameId, serializer);
        sse_encode_list_log_line_view(lines, serializer);
      case UiEvent_GameCrashed(
        gameId: final gameId,
        instanceId: final instanceId,
        crashReport: final crashReport,
      ):
        sse_encode_i_32(5, serializer);
        sse_encode_u_64(gameId, serializer);
        sse_encode_String(instanceId, serializer);
        sse_encode_opt_String(crashReport, serializer);
      case UiEvent_GameExited(
        gameId: final gameId,
        instanceId: final instanceId,
        code: final code,
        secondsPlayed: final secondsPlayed,
      ):
        sse_encode_i_32(6, serializer);
        sse_encode_u_64(gameId, serializer);
        sse_encode_String(instanceId, serializer);
        sse_encode_opt_box_autoadd_i_32(code, serializer);
        sse_encode_u_64(secondsPlayed, serializer);
    }
  }

